import{_ as a,o,c as t,a2 as n}from"./chunks/framework.B0p3fmqd.js";const g=JSON.parse('{"title":"Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"moneywash/changelog.md","filePath":"moneywash/changelog.md","lastUpdated":null}'),i={name:"moneywash/changelog.md"};function l(r,e,s,d,h,c){return o(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><h2 id="_5-1-1" tabindex="-1">5.1.1 <a class="header-anchor" href="#_5-1-1" aria-label="Permalink to &quot;5.1.1&quot;">​</a></h2><h3 id="new" tabindex="-1">New <a class="header-anchor" href="#new" aria-label="Permalink to &quot;New&quot;">​</a></h3><ul><li>A <strong>Max</strong> button on the wash screen, and <strong>-10</strong> / <strong>+10</strong> buttons on every amount selector with a large range.</li></ul><h3 id="changed" tabindex="-1">Changed <a class="header-anchor" href="#changed" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>The number between the - and + buttons is wider, so 3 and 4 digit amounts fit.</li></ul><h3 id="fixed" tabindex="-1">Fixed <a class="header-anchor" href="#fixed" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>You can wash more than 99 dirty money items at once. The amount is limited only by what you carry.</li><li>The same limit of 99 is gone from token crafting, adding tokens to the shop and buying tokens from the shop.</li></ul><div class="tip custom-block"><p class="custom-block-title">Updating</p><p>Interface-only update. There are no config or locale changes, so nothing to merge.</p></div><h2 id="_5-1-0" tabindex="-1">5.1.0 <a class="header-anchor" href="#_5-1-0" aria-label="Permalink to &quot;5.1.0&quot;">​</a></h2><h3 id="new-1" tabindex="-1">New <a class="header-anchor" href="#new-1" aria-label="Permalink to &quot;New&quot;">​</a></h3><ul><li><code>Config.MaxNoteWorth</code>: the most a single dirty money item can wash for.</li><li>Tokens can be added to the shop from the crafting spot as well as the boss menu.</li></ul><h3 id="changed-1" tabindex="-1">Changed <a class="header-anchor" href="#changed-1" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>Dirty money with no stamped value defaults to $1 per item. It used to be a random 100 to 5000.</li><li><code>Config.UseMetadataWorth</code> is on by default.</li><li>The token recipe uses standard inventory items.</li></ul><h3 id="fixed-1" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-1" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>A finished wash can only be collected once.</li><li>The amount to wash is validated, and money is valued lowest first so a large item cannot be washed repeatedly.</li></ul><div class="warning custom-block"><p class="custom-block-title">Updating</p><p>Config files are replaced when you update. If you edited <code>config.lua</code>, merge your values into the new file. Servers still on a <code>BlackMoneyWorth</code> of 100 to 5000 should change it to <code>{ min = 1, max = 1 }</code>.</p></div>',17)])])}const m=a(i,[["render",l]]);export{g as __pageData,m as default};
